function startState(){let b=Array(81).fill(null),back=['L','N','S','G','K','G','S','N','L'];for(let i=0;i<9;i++){b[i]={k:back[i],o:-1};b[72+i]={k:back[8-i],o:1};b[18+i]={k:'P',o:-1};b[54+i]={k:'P',o:1}}b[10]={k:'R',o:-1};b[16]={k:'B',o:-1};b[64]={k:'B',o:1};b[70]={k:'R',o:1};return {b,h:{1:{},'-1':{}},t:1,log:[],last:null}}
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
async function waitPublicApp(page,timeout=150000){const end=Date.now()+timeout;let last=null;while(Date.now()<end){try{last=await page.evaluate(()=>({url:location.href,coi:crossOriginIsolated,cards:document.querySelectorAll('#chars .ch').length,future:window.AI_SHOGI_YANEURAOU_FUTURE?.strengthTune,save:window.AI_SHOGI_SAVE?.version,cloud:window.AI_SHOGI_CLOUD_SAVE?.version,cloudBtn:!!document.getElementById('cloudSaveBtn'),pullBtn:!!document.getElementById('cloudPullBtn')}));if(last.coi&&last.cards===26&&last.future==='fullsearch-20260825'&&last.save==='21530a'&&last.cloud==='21531c'&&last.cloudBtn&&last.pullBtn)return last}catch{}await sleep(500)}throw new Error('public app timeout '+JSON.stringify(last))}
async function openPublic(page,label){await page.goto(`${BASE}/index.html?pr87public=${encodeURIComponent(label)}-${Date.now()}`,{waitUntil:'domcontentloaded',timeout:120000});return await waitPublicApp(page)}
async function realReplyAndSave(page){await page.locator('#chars .ch').nth(25).click();await page.selectOption('#sideSelect2157','sente');await page.click('#newBtn');await page.waitForTimeout(120);const before=(await page.locator('#moves').textContent()||'').trim();await page.locator('#board').locator(':scope > *').nth(56).click();await page.waitForTimeout(50);await page.locator('#board').locator(':scope > *').nth(47).click();await page.waitForFunction(b=>{const t=(document.getElementById('moves')?.textContent||'').trim();return t&&t!==b},before,{timeout:10000});const human=(await page.locator('#moves').textContent()||'').trim();await page.waitForFunction(h=>{const t=(document.getElementById('moves')?.textContent||'').trim(),s=(document.getElementById('status')?.textContent||'');return t!==h&&!/考えています/.test(s)},human,{timeout:120000});await page.waitForFunction(()=>window.AI_SHOGI_SAVE?.audit().savedPly>=2,{timeout:10000});return await page.evaluate(()=>({audit:window.AI_SHOGI_SAVE.audit(),data:window.AI_SHOGI_SAVE.data(),moves:(document.getElementById('moves')?.textContent||'').trim()}))}

for(const c of cases){const browser=await c.type.launch({headless:true});const ctx=await browser.newContext({userAgent:c.ua,viewport:c.viewport});const page=await ctx.newPage();const errors=[];page.on('pageerror',e=>errors.push('pageerror:'+String(e.message||e)));page.on('console',m=>{if(m.type()==='error'&&!/favicon|Data URL decoding failed|ERR_INVALID_URL|Load request cancelled|Failed to load resource|A ServiceWorker intercepted|COI fetch failed/i.test(m.text()))errors.push('console:'+m.text())});try{const first=await openPublic(page,c.name);const init=await page.evaluate(()=>({url:location.href,coi:crossOriginIsolated,cards:document.querySelectorAll('#chars .ch').length,unique:new Set([...document.querySelectorAll('#chars .ch')].map(x=>(x.querySelector('.chName')?.textContent||x.querySelector('img')?.alt||'').trim())).size,future:{index:window.AI_SHOGI_YANEURAOU_FUTURE.index,rating:window.AI_SHOGI_YANEURAOU_FUTURE.rating,tune:window.AI_SHOGI_YANEURAOU_FUTURE.strengthTune},cloud:window.AI_SHOGI_CLOUD_SAVE.audit(),save:window.AI_SHOGI_SAVE.audit(),overflow:document.documentElement.scrollWidth>innerWidth+1}));assert.equal(init.coi,true);assert.equal(init.cards,26);assert.equal(init.unique,26);assert.deepEqual(init.future,{index:25,rating:3400,tune:'fullsearch-20260825'});assert.equal(init.cloud.backend,'supabase-edge-cas-v1');assert.equal(init.cloud.buttons.cloud,true);assert.equal(init.cloud.buttons.pull,true);assert.equal(init.overflow,false);const eng=await page.evaluate(async st=>{const a=window.AI_SHOGI_YANEURAOU_FUTURE,t0=performance.now();await a.init();const r=await a.bestMove(st,{ms:300,multiPV:1,adaptive:false});return {initMs:Math.round(performance.now()-t0),status:a.status(),result:r,info:r?.info||{}}},startState());assert.equal(eng.status.ready,true);assert.equal(eng.status.worker,true);assert.equal(eng.info.hashMB,c.hash);assert.equal(eng.info.threads,1);assert.equal(eng.info.adaptive,false);assert.ok(eng.result?.move||eng.result?.resign||eng.result?.declareWin);assert.equal(await page.evaluate(()=>{window.AI_SHOGI_PIECE_SOUND.setEnabled(false);return window.AI_SHOGI_PIECE_SOUND.enabled}),false);await page.reload({waitUntil:'domcontentloaded',timeout:120000});await waitPublicApp(page);assert.equal(await page.evaluate(()=>window.AI_SHOGI_PIECE_SOUND.enabled),false);await page.evaluate(()=>window.AI_SHOGI_PIECE_SOUND.setEnabled(true));const saved=await realReplyAndSave(page);const ply=saved.audit.savedPly;assert.ok(ply>=2);assert.equal(saved.audit.savedPly,saved.audit.currentPly);assert.equal(saved.data.ci,25);await page.reload({waitUntil:'domcontentloaded',timeout:120000});await waitPublicApp(page);assert.equal((await page.evaluate(()=>window.AI_SHOGI_SAVE.audit())).savedPly,ply);assert.equal(await page.evaluate(()=>window.AI_SHOGI_SAVE.load()),true);const loaded=await page.evaluate(()=>({a:window.AI_SHOGI_SAVE.audit(),opp:(document.getElementById('oppName')?.textContent||'').trim(),cloud:window.AI_SHOGI_CLOUD_SAVE.audit()}));assert.equal(loaded.a.currentPly,ply);assert.equal(loaded.a.currentCharacter,25);assert.ok(loaded.opp.includes('未来からやってきたみつき'));assert.equal(loaded.cloud.hasLocal,true);assert.deepEqual(errors,[]);console.log('PR87_PUBLIC_FOUR_ENV_ROW '+JSON.stringify({name:c.name,url:first.url,hash:c.hash,coi:true,cards:26,unique:26,backend:init.cloud.backend,engine:{initMs:eng.initMs,depth:eng.info.depth,nodes:eng.info.nodes,hashMB:eng.info.hashMB,threads:eng.info.threads},soundPersist:true,futureRealReply:true,savedPly:ply,reloadRestore:true,overflow:false,errors}))}finally{await browser.close()}}

async function seedDevice(ctx,deviceId){await ctx.addInitScript(({deviceId,CLOUD})=>{localStorage.setItem('aiShogiCloudConfigV1',JSON.stringify({syncKey:'',deviceId,api:CLOUD,enabled:false}));localStorage.setItem('aiShogiCloudMetaV1',JSON.stringify({revision:0,lastSyncedSavedAt:0,pending:false,lastError:'',updatedAt:Date.now()}));localStorage.removeItem('aiShogiGameSaveV1')},{deviceId,CLOUD})}
async function crossDevice(name,type,ua,viewport){const browser=await type.launch({headless:true});const a=await browser.newContext({userAgent:ua,viewport}),b=await browser.newContext({userAgent:ua,viewport});await seedDevice(a,`postmerge_ci_${name}_a`);await seedDevice(b,`postmerge_ci_${name}_b`);const pa=await a.newPage(),pb=await b.newPage();const errors=[];for(const p of[pa,pb]){p.on('pageerror',e=>errors.push(String(e)));p.on('console',m=>{if(m.type()==='error'&&!/favicon|Data URL decoding failed|ERR_INVALID_URL|Load request cancelled|Failed to load resource|A ServiceWorker intercepted|COI fetch failed/i.test(m.text()))errors.push(m.text())})}try{await openPublic(pa,`${name}-A`);const saved=await realReplyAndSave(pa);const ply=saved.audit.savedPly;const code=crypto.randomBytes(24).toString('base64url');assert.equal(await pa.evaluate(code=>window.AI_SHOGI_CLOUD_SAVE.enableWithCode(code),code),true);await pa.waitForFunction(()=>window.AI_SHOGI_CLOUD_SAVE.meta().revision===1&&!window.AI_SHOGI_CLOUD_SAVE.meta().pending,{timeout:15000});await openPublic(pb,`${name}-B`);assert.equal(await pb.evaluate(code=>window.AI_SHOGI_CLOUD_SAVE.enableWithCode(code),code),true);await pb.waitForFunction(ply=>window.AI_SHOGI_SAVE?.audit().currentPly===ply,ply,{timeout:15000});let sb=await pb.evaluate(()=>({a:window.AI_SHOGI_SAVE.audit(),m:window.AI_SHOGI_CLOUD_SAVE.meta(),data:window.AI_SHOGI_SAVE.data()}));assert.equal(sb.a.currentPly,ply);assert.equal(sb.a.currentCharacter,25);assert.equal(sb.m.revision,1);
const bPayload=await pb.evaluate(()=>{const x=window.AI_SHOGI_SAVE.data();x.savedAt=Date.now()+1000;x.st.log=[...(x.st.log||[]),{cloudTest:'B'}];localStorage.setItem('aiShogiGameSaveV1',JSON.stringify(x));window.dispatchEvent(new Event('ai-shogi-local-save'));return x});await pb.waitForFunction(()=>window.AI_SHOGI_CLOUD_SAVE.meta().revision===2&&!window.AI_SHOGI_CLOUD_SAVE.meta().pending,{timeout:15000});const aPayload=await pa.evaluate(()=>{const x=window.AI_SHOGI_SAVE.data();x.savedAt=Date.now()+2000;x.st.log=[...(x.st.log||[]),{cloudTest:'A-pending'}];localStorage.setItem('aiShogiGameSaveV1',JSON.stringify(x));window.dispatchEvent(new Event('ai-shogi-local-save'));return x});await pa.waitForFunction(()=>window.AI_SHOGI_CLOUD_SAVE.meta().pending&&window.AI_SHOGI_CLOUD_SAVE.meta().lastError==='conflict',{timeout:15000});const protectedPull=await pa.evaluate(()=>window.AI_SHOGI_CLOUD_SAVE.pull());assert.equal(protectedPull.localPending,true);const beforeDiscard=await pa.evaluate(()=>JSON.parse(localStorage.getItem('aiShogiGameSaveV1')).st.log.at(-1).cloudTest);assert.equal(beforeDiscard,'A-pending');pa.once('dialog',d=>d.accept());await pa.click('#cloudPullBtn');await pa.waitForFunction(()=>{const x=JSON.parse(localStorage.getItem('aiShogiGameSaveV1')||'null');return window.AI_SHOGI_CLOUD_SAVE.meta().revision===2&&!window.AI_SHOGI_CLOUD_SAVE.meta().pending&&x?.st?.log?.at(-1)?.cloudTest==='B'},{timeout:15000});const final=await pa.evaluate(()=>({m:window.AI_SHOGI_CLOUD_SAVE.meta(),last:JSON.parse(localStorage.getItem('aiShogiGameSaveV1')).st.log.at(-1),a:window.AI_SHOGI_SAVE.audit()}));assert.equal(final.m.revision,2);assert.equal(final.last.cloudTest,'B');assert.deepEqual(errors,[]);console.log('PR87_PUBLIC_CROSS_DEVICE_ROW '+JSON.stringify({browser:name,public:true,backend:'supabase-edge-cas-v1',initialPly:ply,deviceBRestore:true,revision2:true,conflictProtected:true,explicitDiscardRestore:true,errors}))}finally{await a.close();await b.close();await browser.close()}}
await crossDevice('webkit',webkit,cases[0].ua,cases[0].viewport);
await crossDevice('chromium',chromium,cases[2].ua,cases[2].viewport);
